402	/** Delete one backup archive by its Proxmox volume id. `client` = the node's pve client. */
403	export async function deleteBackup(client: any, volid: string): Promise<void> {
404	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
405	}
