452	async function suspend(job: Job, unsuspend: boolean) {
453	  const server = await loadServer(job);
454	  if (SANDBOX) {
455	    if (unsuspend) {
456	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null } });
457	    } else {
458	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
459	    }
460	    return;
461	  }
462	  const { conn, row: nodeRow } = await nodeFor(server);
463	  if (unsuspend) {
464	    // The dedicated IP was returned to the pool while suspended — re-allocate one
465	    // and reconfigure the public network before starting the VM back up.
466	    if (server.vmid) {
467	      const { getSettingBool: _sb } = await import("../lib/settings");
468	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
469	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
470	      let reconfigured = alreadyHas ? true : false;
471	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
472	        try {
473	          const d = await allocateDedicatedIp(server.id, server.vmid);
474	          if (d) {
475	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
476	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
477	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
478	            });
479	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
480	            reconfigured = true;
481	          }
482	        } catch (e) {
483	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
484	        }
485	      }
486	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
487	      // the Virtual MAC + failover IP that suspend released back to the pool — that
488	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
489	      // with a valid, non-conflicting network instead of a dead public config.
490	      if (!reconfigured) {
491	        try {
492	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
493	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
494	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
495	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
496	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
497	          });
498	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
499	        } catch (e) {
500	          console.error("[worker] NAT fallback on unsuspend failed", e);
501	        }
502	      }
503	    }
504	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
505	    if (!SANDBOX) await syncPortForwards();
506	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
507	    await conn.waitForTask(upid);
508	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
509	  } else {
510	    try {
511	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
512	      await conn.waitForTask(upid);
513	    } catch { /* may already be stopped */ }
514	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
515	    if (!SANDBOX) await syncPortForwards();
516	    // Return the dedicated IP to the pool while the server is suspended, so it
517	    // can be handed to a paying server. Re-allocated on unsuspend.
518	    if (ovhConfigured()) {
519	      try {
520	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
521	        if (had) {
522	          await releaseDedicatedIp(server.id);
523	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
524	          // so leaving the released IP here makes the next server that claims it fail
525	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
526	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
527	          await db.server.update({
528	            where: { id: server.id },
529	            data: { ipAddress: null, ipv6: null },
530	          });
531	        }
532	      } catch (e) {
533	        console.error("[worker] release dedicated IP on suspend failed", e);
534	      }
535	    }
536	  }
537	}
