547	async function resize(job: Job) {
548	  const server = await loadServer(job);
549	  const payload = (job.payload ?? {}) as { planId?: string };
550	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
551	  if (!newPlan) throw new Error("resize: target plan not found");
552	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
553	
554	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
555	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
556	  // never written here. Sizes below are therefore always the EFFECTIVE size
557	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
558	  // disk of any server carrying extra storage, and the resize would hard-fail.
559	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
560	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
561	  const diskLine =
562	    server.extraDiskGB > 0
563	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
564	      : `${newPlan.diskGB} GB disk`;
565	
566	  if (SANDBOX) {
567	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
568	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
569	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
570	      `/dashboard/servers/${server.id}`);
571	    return;
572	  }
573	
574	  const { conn } = await nodeFor(server);
575	  const wasRunning = server.status === "RUNNING";
576	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
577	    cores: newPlan.cpuCores,
578	    memory: newPlan.ramMB,
579	  });
580	  if (newTotalDiskGB > currentTotalDiskGB) {
581	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
582	      disk: "scsi0",
583	      size: `${newTotalDiskGB}G`,
584	    });
585	  }
586	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
587	  // CPU/RAM changes need a power cycle to apply
588	  if (wasRunning) {
589	    try {
590	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
591	      await conn.waitForTask(stopUpid, 120_000);
592	    } catch {
593	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
594	      await conn.waitForTask(stopUpid);
595	    }
596	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
597	    await conn.waitForTask(startUpid);
598	  }
599	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
600	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
601	    `/dashboard/servers/${server.id}`);
602	}
