613	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
614	      `/dashboard/servers/${server.id}`
615	    );
616	    return;
617	  }
618	  const { conn } = await nodeFor(server);
619	  let upid: string;
620	  if (op === "create") {
621	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
622	  } else if (op === "delete") {
