628	  if (op === "rollback") {
629	    // rollback leaves the VM stopped; bring it back if the server should be running
630	    const current = await db.server.findUnique({ where: { id: server.id } });
631	    if (current?.status === "RUNNING") {
632	      try {
633	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
634	        await conn.waitForTask(startUpid);
635	      } catch { /* may already be running */ }
636	    }
637	  }
638	}
