641	  const server = await loadServer(job);
642	  if (SANDBOX) {
643	    // Sandbox: rotate the stored password only — never touch a real VM.
644	    const password = generatePassword();
645	    await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
646	    await notify(
