649	      "Your new root password is on the server's Overview tab (no real VM was touched).",
650	      `/dashboard/servers/${server.id}`
651	    );
652	    return;
653	  }
654	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
655	  const { conn } = await nodeFor(server);
656	  const password = generatePassword();
657	
658	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
659	  let applied = false;
660	  try {
