747	    { timeoutMs: 3_600_000, phase: "backup" }
748	  );
749	  await reportJobProgress(job.id, 100, "Backup complete");
750	  // Retention: keep only the latest few backups for this server; prune the rest.
751	  if (server.vmid != null) {
