755	    } catch (e) {
756	      console.error(`[backup] prune failed for vmid ${server.vmid}`, e);
757	    }
758	  }
759	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
760	    `/dashboard/servers/${server.id}`);
