817	  if (cents <= 0 || !job.serverId) return;
818	
819	  const already = await db.auditLog.findFirst({
820	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
821	  });
822	  if (already) return;
823	
824	  const server = await db.server.findUnique({
825	    where: { id: job.serverId },
826	    select: { userId: true, hostname: true, extraDiskGB: true },
827	  });
828	  if (!server) return;
829	
830	  // The expansion actually landed (or a later one superseded it) — the customer
831	  // has the storage, so the charge stands. Nothing to unwind.
832	  const target = Number(p.targetExtraDiskGB ?? 0);
833	  if (target > 0 && server.extraDiskGB >= target) return;
834	
835	  try {
836	    await db.$transaction([
837	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
838	      db.walletTransaction.create({
839	        data: {
840	          userId: server.userId,
841	          amountCents: cents,
842	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
843	        },
844	      }),
845	      db.notification.create({
846	        data: {
847	          userId: server.userId,
