849	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
850	          href: `/dashboard/servers/${job.serverId}`,
851	        },
852	      }),
853	    ]);
854	    await db.auditLog.create({
855	      data: {
856	        userId: server.userId,
857	        action: "server.disk_expand.reconcile",
858	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
859	      },
860	    });
861	  } catch (e: any) {
862	    await db.auditLog
863	      .create({
864	        data: {
865	          userId: server.userId,
866	          action: "server.disk_expand.reconcile.uncharged",
867	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
