881	 * double-reverse.
882	 */
883	async function reconcileFailedJob(job: Job) {
884	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
885	  if (job.type !== "RESIZE") return;
886	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
887	  const cents = p.prorateCents ?? 0;
888	  if (cents <= 0 || !job.serverId) return;
889	
890	  // Idempotency: skip if we already reversed this exact job.
891	  const already = await db.auditLog.findFirst({
892	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
893	  });
894	  if (already) return;
895	
896	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
897	  if (!server) return;
898	
899	  try {
900	    if (p.direction === "up") {
901	      // Upgrade charge never delivered → refund the prorated charge.
902	      await db.$transaction([
903	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
904	        db.walletTransaction.create({
905	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
906	        }),
907	      ]);
908	    } else if (p.direction === "down") {

908	    } else if (p.direction === "down") {
909	      // Downgrade credit was given but hardware unchanged → claw the credit back.
910	      // Guarded so it can never drive the balance negative; if the customer already
911	      // spent it, we log and leave it (best-effort — they keep a small windfall).
912	      await db.$transaction(async (tx) => {
913	        await debitWallet(tx, server.userId, cents);
914	        await tx.walletTransaction.create({
915	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
916	        });
917	      });
918	    }
919	    await db.auditLog.create({
920	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
921	    });
922	  } catch (e: any) {
923	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
924	    await db.auditLog.create({
925	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
