930	async function runJob(job: Job) {
931	  // The job is already atomically claimed (status RUNNING, attempts incremented)
932	  // by the loop's compare-and-swap before we get here — see the CAS in main().
933	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
934	  try {
935	    await handlers[job.type](job);
936	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
937	    console.log(`[worker] job ${job.id} DONE`);
938	  } catch (e: any) {
939	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
940	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
941	    // leak the server's root password into the thrown message. Redact it before
942	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
943	    // sever the match. Best-effort — never let redaction lookup fail the job path.
944	    if (job.serverId) {
945	      try {
946	        const s = await db.server.findUnique({
947	          where: { id: job.serverId },
948	          select: { rootPassword: true, rootPasswordEnc: true },
949	        });
950	        const pw = s ? serverRootPassword(s) : null;
951	        if (pw) error = error.split(pw).join("***");
952	      } catch {
953	        /* best-effort redaction */
954	      }
955	    }
956	    error = error.slice(0, 2000);
957	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
958	    const current = await db.job.findUnique({ where: { id: job.id } });
959	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
960	    await db.job.update({
961	      where: { id: job.id },
962	      data: { status: retriable ? "QUEUED" : "FAILED", error },
963	    });
964	    if (!retriable) {
965	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
966	      if (job.serverId) {
967	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
968	        if (stillExists) {
969	          // Only jobs that actually change the VM's run/disk state should strand the
970	          // server in ERROR. Side operations — backup, snapshot-create, the control-
971	          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
972	          // never touch the VM's run state; their failures surface via the executor's
973	          // own notification and must NOT flip the whole server to ERROR (a failed
974	          // backup was wrongly making the server look like it had shut down).
975	          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
976	            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
977	          }
978	          // A terminally-failed PROVISION must not leak its allocated dedicated IP:
979	          // release it back to the pool (deletes the billable OVH Virtual MAC) and
980	          // clear the (UNIQUE) ipAddress so the next server can claim it.
981	          if (job.type === "PROVISION" && !SANDBOX) {
982	            await releaseDedicatedIp(job.serverId).catch((err) =>
983	              console.error(`[worker] release dedicated IP on failed provision ${job.id}`, err)
984	            );
985	            await db.server
986	              .update({ where: { id: job.serverId }, data: { ipAddress: null } })
987	              .catch(() => {});
988	          }
989	        }
990	      }
991	    }
992	  }
993	}
