136	/**
137	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
138	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
139	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
140	 * otherwise). A prorated credit for the price difference over the remaining term
141	 * is returned to the wallet.
142	 */
143	export async function resizeServerDown(
144	  serverId: string,
145	  newPlanId: string
146	): Promise<{ error?: string }> {
147	  const { user, server } = await ownedServer(serverId);
148	
149	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
150	  if (!newPlan?.active) return { error: "Plan not available." };
151	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
152	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
