158	  // Disk can't shrink destructively; block the move rather than lose data.
159	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
160	  // both the old and the new plan and is preserved verbatim across the resize, so
161	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
162	  // does not shrink". Nothing here ever writes extraDiskGB.
163	  if (newPlan.diskGB < server.plan.diskGB) {
164	    return {
165	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
166	    };
167	  }
168	
169	  if (await hasInflightJob(serverId)) {
170	    return { error: "Another operation is already in progress on this server." };
171	  }
172	
173	  // Prorated credit over the ACTUAL remaining duration, not a fraction of a single
174	  // term. `renewNow` can stack expiresAt many terms into the future, so the old
175	  // "fraction of one term" clamp under-credited (or over-credited) prepaid users.
176	  // Credit the monthly price difference for every remaining month. Null expiresAt
177	  // (free/admin servers) => 0.
178	  let creditCents = 0;
179	  if (!server.isFree && server.expiresAt) {
180	    const now = Date.now();
181	    const remainingMonths = Math.max(0, (server.expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
182	    const monthlyDelta = server.plan.priceCents - newPlan.priceCents; // positive: old monthly > new monthly
183	    creditCents = Math.max(0, Math.round(monthlyDelta * remainingMonths));
184	  }
185	
186	  await db.$transaction([
187	    ...(creditCents > 0
188	      ? [
189	          db.user.update({
190	            where: { id: server.userId },
191	            data: { balanceCents: { increment: creditCents } },
192	          }),
193	          db.walletTransaction.create({
194	            data: {
195	              userId: server.userId,
196	              amountCents: creditCents,
197	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
198	            },
199	          }),
200	        ]
201	      : []),
202	    // Record the amount credited on the job so the worker's RESIZE handler can
203	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
204	    // terminally fails — the credit is committed here, before the job runs.
205	    // INTEGRATION NEEDED: worker must honour payload.prorateCents/direction.
206	    db.job.create({
207	      data: {
208	        type: "RESIZE",
209	        serverId,
210	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
211	      },
212	    }),
213	    db.auditLog.create({
214	      data: {
215	        userId: user.id,
216	        action: "server.resize_down",
217	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
218	      },
219	    }),
220	  ]);
221	
222	  revalidatePath(`/dashboard/servers/${serverId}`);
223	  return {};
224	}
