20	async function queueJob(
21	  serverId: string,
22	  type:
23	    | "SNAPSHOT_CREATE"
24	    | "SNAPSHOT_DELETE"
25	    | "SNAPSHOT_ROLLBACK"
26	    | "BACKUP_CREATE"
