246	  await db.portForward.deleteMany({ where: { id: forwardId, serverId } });
247	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
248	  await db.auditLog.create({
249	    data: { userId: user.id, action: "server.portforward_delete", detail: `${serverId} ${forwardId}` },
250	  });
251	  revalidatePath(`/dashboard/servers/${serverId}`);
252	}
