6	/** Best-effort live progress write onto the running Job row (never throws). */
7	async function reportJobProgress(jobId: string, progress: number, step: string) {
8	  try {
9	    await db.job.update({
10	      where: { id: jobId },
11	      data: { progress: Math.max(0, Math.min(100, Math.round(progress))), step },
12	    });
13	  } catch (e) {
14	    console.error("[restore] job progress update failed", e);
15	  }
16	}
