18	/**
19	 * Self-service backup restore handler.
20	 *
21	 * Restores a selected vzdump archive back onto the server's existing VM via the
22	 * Proxmox API: stop -> restore (force overwrite) -> start. Ownership and archive
23	 * validation are enforced at enqueue time (`lib/actions-server-ops.ts`), so this
24	 * handler trusts the `volid` in the job payload.
25	 *
26	 * NOTE: `worker/index.ts` owns the job loop and its `handlers` map; wire this in
27	 * there as `BACKUP_RESTORE: backupRestore`.
28	 */
29	
30	async function loadServer(serverId: string) {
31	  const server = await db.server.findUnique({
32	    where: { id: serverId },
33	    include: { node: true },
34	  });
35	  if (!server) throw new Error(`Server ${serverId} not found`);
36	  return server;
37	}
