39	/** Resolve a Proxmox client for the server's node (mirrors worker/index.ts). */
40	async function nodeFor(server: any) {
41	  const n =
42	    server.node ??
43	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
44	    (await db.node.findFirst({ where: { enabled: true } }));
45	  if (!n) {
46	    return {
47	      get: pve.get,
48	      post: pve.post,
49	      put: pve.put,
50	      del: pve.del,
51	      node: envNode,
52	      waitForTask,
53	      nextVmid,
54	      vmStatus: (v: number) => pve.get(`/nodes/${envNode}/qemu/${v}/status/current`),
55	    } as any;
56	  }
57	  return pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret });
58	}
