68	export async function backupRestore(job: Job): Promise<void> {
69	  const server = await loadServer(job.serverId!);
70	  if (SANDBOX) {
71	    // Simulate a successful restore — animate the bar 0→100 so staging shows it.
72	    const steps = [
73	      { pct: 8, step: "Stopping server" },
74	      { pct: 30, step: "Restoring archive… 25%" },
75	      { pct: 55, step: "Restoring archive… 55%" },
76	      { pct: 80, step: "Restoring archive… 85%" },
77	      { pct: 95, step: "Starting server" },
78	      { pct: 100, step: "Restore complete" },
79	    ];
80	    for (const s of steps) {
81	      await reportJobProgress(job.id, s.pct, s.step);
82	      await new Promise((r) => setTimeout(r, 500));
83	    }
84	    await notify(
85	      server.userId,
86	      `Backup restored on ${server.hostname}`,
87	      "Your server was restored from the selected backup (sandbox).",
88	      `/dashboard/servers/${server.id}`
89	    );
90	    return;
91	  }
92	  if (!server.vmid) throw new Error("restore: server has no VM");
93	
94	  const payload = (job.payload ?? {}) as { volid?: string };
95	  const volid = payload.volid;
96	  if (!volid) throw new Error("restore: missing volid");
97	
98	  const conn = await nodeFor(server);
99	  const vmid = server.vmid;
100	  const wasRunning = server.status === "RUNNING";
101	
102	  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
103	  await reportJobProgress(job.id, 3, "Stopping server");
104	  try {
105	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
106	    await conn.waitForTask(stopUpid);
107	  } catch {
108	    /* already stopped / not running */
109	  }
110	  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
111	
112	  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
113	  //    left to the archive's recorded config so disks land where they were.
114	  //    Task progress (0..100) is mapped into the 10..90 window of the bar.
115	  await reportJobProgress(job.id, 10, "Restoring archive…");
116	  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
117	    vmid,
118	    archive: volid,
119	    force: 1,
120	  });
121	  await waitForTaskProgress(
122	    conn,
123	    restoreUpid,
124	    (progress, step) => reportJobProgress(job.id, progress, step),
125	    { timeoutMs: 3_600_000, phase: "restore", base: 10, span: 80 }
126	  );
127	
128	  // 3) Bring the VM back up if it was running before the restore.
129	  if (wasRunning) {
130	    await reportJobProgress(job.id, 95, "Starting server");
131	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
132	    await conn.waitForTask(startUpid);
133	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
134	  }
135	  await reportJobProgress(job.id, 100, "Restore complete");
136	
137	  await notify(
138	    server.userId,
139	    `Backup restored on ${server.hostname}`,
140	    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
141	    `/dashboard/servers/${server.id}`
142	  );
143	}
