10	/**
11	 * Server-ops actions: game-server auto-update toggle + "update now", and
12	 * self-service backup restore. Every action re-verifies ownership.
13	 */
14	
15	async function ownedServer(serverId: string) {
16	  const user = await requireUser();
17	  const server = await db.server.findUnique({
18	    where: { id: serverId },
19	    include: { osTemplate: true },
20	  });
21	  if (!server) throw new Error("Not found");
22	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
23	  return { user, server };
24	}
25	
26	/** Is this server's image a managed game family? */
27	function isGameServer(server: { osTemplate: { family: string } }): boolean {
28	  return GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
29	}
