export async function orderEmailHosting(
  domainName: string,
  emailPlanId: string,
): Promise<Result> {
  const user = await requireUser();

  const name = String(domainName ?? "")
    .trim()
    .toLowerCase()
    .replace(/\.$/, "");
  if (!name) return { error: "Enter a domain." };
  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };

  // Is the domain registered inside Nxeon? If so we control its DNS and can
  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
  // verified via DNS before mail flows.
  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
  const external = !inAccount;

  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };

  // One subscription per domain — refuse a duplicate.
  const dupe = await db.emailSubscription.findFirst({
    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
  });
  if (dupe) return { error: "This domain already has an email subscription." };

  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
  // strikethrough shown on the pricing page is the real renewal price and this
  // discounted value is the real first-term price — displayed === charged.
  const promo = currentPromo(new Date());
  const chargeCents = promoPriceCents(plan.priceCents, promo);
  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  try {
    await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
        },
      });
      await tx.emailSubscription.create({
        data: {
          userId: user.id,
          domainName: name,
          emailPlanId: plan.id,
          status: "ACTIVE",
          autoRenew: true,
          expiresAt: addMonths(new Date(), plan.termMonths),
          // In-account domains: we control DNS, so treat as verified now. External
          // domains: not verified until the customer publishes DNS + we confirm it.
          external,
          verified: !external,
          verifiedAt: external ? null : new Date(),
          verifyToken: external ? randomBytes(24).toString("hex") : null,
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }

}

// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;

/**
 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
 * quota and address uniqueness within the subscription, records the intended
 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
 */
export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({
    where: { id: subscriptionId },
    include: { emailPlan: true, mailboxes: true },
  });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };
  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };

  const local = String(localPart ?? "").trim().toLowerCase();
  if (!localPartRe.test(local) || local.length > 64) {
    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
  }

  const address = `${local}@${sub.domainName}`;

  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
    return {
      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
    };
  }
  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
    return { error: "That address already exists." };
  }

  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
  const quotaMB = sub.emailPlan.storageGB * 1024;

  const mailbox = await db.mailbox.create({
    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.add", detail: address },
  });

  // Additive, failure-tolerant provisioning — never throws out of the flow.
  await provisionMailboxOnMailcow({
    id: mailbox.id,
    address: mailbox.address,
    quotaMB,
    subscription: { domainName: sub.domainName },
  });

  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * Re-attempt Mailcow provisioning for a mailbox stuck in PROVISIONING/FAILED.
 * Owner-only (the caller must own the mailbox via its subscription).
 */
export async function retryMailboxProvision(mailboxId: string): Promise<Result> {
  if (status === "FAILED") return { error: "Provisioning failed again — check the mail server." };
  return { ok: true };
}

/** Remove a mailbox the caller owns (via its subscription). */
export async function removeMailbox(mailboxId: string): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  // Best-effort delete on Mailcow before dropping the row — a mail-server outage
  // must not block the customer from removing the mailbox record.
  if (mailcowConfigured()) {
    await mcDeleteMailbox(mailbox.address).catch((e) => {
      console.warn(`[mailcow] delete ${mailbox.address} failed:`, e);
    });
  }

  await db.mailbox.delete({ where: { id: mailbox.id } });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.remove", detail: mailbox.address },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
 */
export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  if (mailcowConfigured()) {
    await mcSetMailboxActive(mailbox.address, !suspended).catch((e) => {
      console.warn(`[mailcow] set active ${mailbox.address} failed:`, e);
    });
  }

  await db.mailbox.update({
    where: { id: mailbox.id },
    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
  });

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: suspended ? "mailbox.suspend" : "mailbox.resume",
      detail: mailbox.address,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

// ---------- Mailbox password (reveal / reset) ----------

/** A strong, URL-safe mailbox password (same generator used at provisioning). */
 * rate-limited. The mail-server call must succeed before we store the new value,
 * so a stored password always matches what actually authenticates. Returns the
 * new password once for the customer to copy.
 */
export async function resetMailboxPassword(
  mailboxId: string,
): Promise<{ error?: string; password?: string }> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };

  const rl = checkRateLimit(`mailbox-pwreset:${user.id}:${mailbox.id}`, {
    max: 5,
    windowMs: 60_000,
  });
  if (!rl.ok) return { error: `Too many resets. Try again in ${rl.retryAfterSec}s.` };

  const password = generateMailboxPassword();

  try {
    await mcSetMailboxPassword(mailbox.address, password);
  } catch (e) {
    console.warn(`[mailcow] set password ${mailbox.address} failed:`, e);
    return { error: "Couldn't update the password on the mail server. Try again shortly." };
  }

  await db.mailbox.update({
    where: { id: mailbox.id },
    data: { passwordEnc: encryptSecret(password) },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.pwreset", detail: mailbox.address },
  });
  revalidatePath("/dashboard/email");
  return { password };
}

